"""stages.context: generated by the graph.py split (P1)."""

from __future__ import annotations

from pathlib import Path

from .. import spec as spec_mod, state as state_mod
from ..benchmark import embench, generic
from ..flow import ladder, outcome
from ..runtime import llm_step, stage_services
from ..runtime.llm import DEFAULT_MAX_TOOL_CALLS, DEFAULT_MAX_TOOL_CALLS_PER_ROUND, DEFAULT_MAX_TOOL_ROUNDS, LlmResult
from ..runtime.policy import PolicyError
from ..runtime.tools import DEFAULT_CONTEXT_FILES, DESIGN_SOURCE_FILES, DESIGN_WORKSPACE_SUBDIR, RepoToolbox
from ..state import CfuDesignState


def load_context(state: CfuDesignState) -> CfuDesignState:
    workdir = Path(state.get("workdir", ".")).resolve()
    policy = stage_services._policy(state)
    artifacts = stage_services._artifacts(state, policy)
    toolbox = stage_services._toolbox_for_stage(state, "load_context")

    context_sources = ["agents/specs/cfu_isa_template.yaml"]
    if state.get("benchmark_name"):
        # The workload source is what the LLM analyzes and patches.
        context_sources.extend(embench.benchmark_source_files(workdir, str(state["benchmark_name"])))
    if state.get("kernel_file"):
        context_sources.append(state["kernel_file"])
    if state.get("workload_spec_path"):
        context_sources.append(state["workload_spec_path"])
    files: dict[str, str] = {}
    denied: list[str] = []
    # A context file the selected visibility tier hides is expected, not a policy
    # misconfiguration, so it must not fail the load_context gate.
    withheld: list[str] = []
    seen: set[str] = set()
    for path in [*DEFAULT_CONTEXT_FILES, *context_sources]:
        if path in seen:
            continue
        seen.add(path)
        blocked = policy.visibility_block(path)
        if blocked:
            withheld.append(f"{path}: requires visibility level {blocked!r}")
            continue
        artifact_path = f"01_context/excerpt/{path.replace('/', '__')}.txt"
        try:
            text = toolbox.read_text(path, limit=20000)
        except PolicyError as exc:
            denied.append(f"{path}: {exc}")
            continue
        if not text:
            continue
        files[path] = text
        artifacts.write_text("load_context", artifact_path, text, kind="context_excerpt", inputs=[path])

    # Seed the isolated hardware design workspace from the tracked scaffolds.
    # The agent may only write these two files; the repo copies stay read-only.
    design_toolbox = RepoToolbox(
        workdir,
        dry_run=state.get("dry_run", False),
        policy=policy,
        stage="implementation",
        run_root=artifacts.root_rel,
        apply_patch=state.get("apply_patch", False),
    )
    design_files = design_toolbox.seed_design_workspace()

    manifest = {
        "visibility": policy.visibility,
        "visible_files": sorted(files),
        "withheld_files": withheld,
        "denied_files": denied,
        "git_status": toolbox.git_status(),
        "design_workspace": {
            "root": f"{artifacts.root_rel}/{DESIGN_WORKSPACE_SUBDIR}",
            "files": design_files,
            "seeded_from": list(DESIGN_SOURCE_FILES),
        },
    }
    artifacts.write_yaml("load_context", "01_context/manifest.yaml", manifest, status="produced")
    artifacts.set_manifest_metadata(
        "load_context",
        "visibility",
        {"level": policy.visibility, "withheld": withheld},
    )
    artifacts.set_manifest_metadata(
        "load_context",
        "tool_policy",
        {
            "agent_tools": bool(state.get("agent_tools", True)),
            "max_rounds": int(state.get("max_tool_rounds", DEFAULT_MAX_TOOL_ROUNDS) or DEFAULT_MAX_TOOL_ROUNDS),
            "max_calls": int(state.get("max_tool_calls", DEFAULT_MAX_TOOL_CALLS) or 0),
            "max_calls_per_round": DEFAULT_MAX_TOOL_CALLS_PER_ROUND,
        },
    )
    return {
        "context": {
            "files": files,
            "git_status": manifest["git_status"],
            "visibility": policy.visibility,
            "withheld": withheld,
            # Prompts report where the agent works; run_root lets every
            # artifact reference be written as a full repo-relative path.
            "workdir": str(workdir),
            "run_root": artifacts.root_rel,
        },
        "visibility": policy.visibility,
        "run_id": artifacts.run_id,
        "run_root": artifacts.root_rel,
        "design_workspace": manifest["design_workspace"],
        "design_files": design_files,
        "status": "initialized",
        "stage_jobs": "ingest_input",
        **outcome.stage_result(
            state, rung="load_context", ok=not denied, denied=denied,
            history=f"Loaded repo context ({policy.visibility} visibility) and seeded the isolated CFU design workspace.",
        ),
    }


def ingest_input(state: CfuDesignState) -> CfuDesignState:
    workdir = Path(state.get("workdir", ".")).resolve()
    policy = stage_services._policy(state)
    artifacts = stage_services._artifacts(state, policy)
    llm_raw_outputs: list[str] = []

    # The spec call builds its prompt internally; the sink captures it so the
    # call leaves its prompt behind like every other LLM call in the run.
    prompt_box = {"system": "", "user": ""}

    def record_spec_prompt(system: str, user: str) -> None:
        prompt_box["system"] = system
        prompt_box["user"] = user

    def record_spec_output(_label: str, result: LlmResult) -> None:
        llm_raw_outputs.append(
            llm_step._record_llm_output(
                state, "ingest_input", "spec", result,
                system=prompt_box["system"], user=prompt_box["user"],
            )
        )

    spec, spec_text = spec_mod.normalize_workload_spec(
        task=state.get("task", ""),
        input_mode=state.get("input_mode", "natural_language"),
        context=state.get("context", {}),
        workdir=workdir,
        workload_spec_path=state.get("workload_spec_path", ""),
        project_root=state.get("project_root", ""),
        kernel_file=state.get("kernel_file", ""),
        kernel_function=state.get("kernel_function", ""),
        build_cmd=state.get("build_cmd", ""),
        run_cmd=state.get("run_cmd", ""),
        test_cmd=state.get("test_cmd", ""),
        benchmark_name=state.get("benchmark_name", ""),
        llm=llm_step._llm(state),
        llm_result_sink=record_spec_output,
        llm_prompt_sink=record_spec_prompt,
    )
    problems = spec_mod.validate_workload_spec(spec)
    artifacts.write_yaml("ingest_input", "02_workload/workload_spec.yaml", dict(spec), status="produced")
    artifacts.write_yaml(
        "ingest_input",
        "02_workload/validation.yaml",
        {"status": "valid" if not problems else "invalid", "problems": problems},
    )
    return {
        "workload_spec": spec,
        "spec_text": spec_text,
        "spec_unknowns": spec.get("unknowns", []),
        "llm_raw_outputs": llm_raw_outputs,
        "stage_jobs": "route_input",
        "status": "blocked" if problems else "initialized",
        **outcome.stage_result(state, rung="workload_spec", ok=not problems, problems=problems,
                               history=f"Normalized input into WorkloadSpec `{spec.get('name', 'cfu_workload')}`."),
    }


def route_input(state: CfuDesignState) -> CfuDesignState:
    kind, _ = ladder._route_kind(state)
    stage_services._artifacts_for_stage(state, "route_input").write_yaml(
        "route_input",
        "03_route/route.yaml",
        {"input_kind": kind, "description": "input classification result"},
    )
    return {
        "input_kind": kind,
        "stage_jobs": "prepare_benchmark",
        "iteration_history": state_mod.append_history(state, f"Selected input route `{kind}`."),
    }


def prepare_c_project_profile_node(state: CfuDesignState) -> CfuDesignState:
    workdir = Path(state.get("workdir", ".")).resolve()
    policy = stage_services._policy(state)
    artifacts = stage_services._artifacts(state, policy)
    workspace = f"{artifacts.root_rel}/workspace"
    spec = dict(state.get("workload_spec", {}))
    spec["project_root"] = state.get("project_root", spec.get("project_root", ""))
    spec["kernel_file"] = state.get("kernel_file", spec.get("kernel_file", ""))
    project = generic.prepare_c_project_profile(
        stage_services._toolbox_for_stage(state, "prepare_benchmark"),
        spec,
    )
    artifacts.write_yaml(
        "prepare_benchmark",
        "04_benchmark/manifest.yaml",
        dict(project),
        status="planned" if state.get("dry_run") else "produced",
    )
    return {
        "benchmark_project": project,
        "stage_jobs": "profile",
        "gates": ladder._prepare_gates(state, "prepare_c_project_profile", "instrument_and_profile"),
        "iteration_history": state_mod.append_history(state, f"Prepared C-project profiling workspace `{project.get('workspace', '')}`."),
    }


def create_benchmark_project_node(state: CfuDesignState) -> CfuDesignState:
    workdir = Path(state.get("workdir", ".")).resolve()
    policy = stage_services._policy(state)
    artifacts = stage_services._artifacts(state, policy)
    project = generic.prepare_generated_benchmark(
        stage_services._toolbox_for_stage(state, "prepare_benchmark"), state.get("workload_spec", {})
    )
    artifacts.write_yaml(
        "prepare_benchmark",
        "04_benchmark/manifest.yaml",
        dict(project),
        status="planned" if state.get("dry_run") else "produced",
    )
    return {
        "benchmark_project": project,
        "stage_jobs": "profile",
        "gates": ladder._prepare_gates(state, "create_benchmark_project", "instrument_and_profile"),
        "iteration_history": state_mod.append_history(state, f"Prepared generated benchmark workspace `{project.get('workspace', '')}`."),
    }


def prepare_embench_benchmark_node(state: CfuDesignState) -> CfuDesignState:
    """Copy an embench-iot benchmark into the run workspace and plan its build."""
    workdir = Path(state.get("workdir", ".")).resolve()
    policy = stage_services._policy(state)
    artifacts = stage_services._artifacts(state, policy)
    spec = dict(state.get("workload_spec", {}))
    toolbox = stage_services._toolbox_for_stage(state, "prepare_benchmark")
    project = embench.prepare_embench_benchmark(toolbox, spec)
    artifacts.write_yaml(
        "prepare_benchmark",
        "04_benchmark/embench.yaml",
        dict(project),
        status="planned" if state.get("dry_run") else "produced",
    )
    return {
        "benchmark_project": project,
        "stage_jobs": "profile",
        "gates": ladder._prepare_gates(state, "embench.prepare_embench_benchmark", "profile_embench"),
        "iteration_history": state_mod.append_history(
            state, f"Prepared embench benchmark `{project.get('benchmark', '')}`."
        ),
    }
